const jwt = require('jsonwebtoken');
const prisma = require('../prisma');

const JWT_SECRET = process.env.JWT_SECRET || 'your_super_secret_jwt_key_here';

/**
 * Customer / User Authentication Middleware
 * Reuses existing JWT tokens generated by your backend auth service.
 */
async function authenticate(req, res, next) {
  try {
    const authHeader = req.headers.authorization;
    if (!authHeader || !authHeader.startsWith('Bearer ')) {
      // Seamless guest session support for mobile app visitors
      const guestId = req.headers['x-guest-id'] || req.body?.guestId || req.query?.guestId;
      if (guestId) {
        let guestUser = await prisma.user.findFirst({
          where: { googleId: `guest_${guestId}` }
        });
        if (!guestUser) {
          guestUser = await prisma.user.create({
            data: {
              name: 'App Visitor',
              googleId: `guest_${guestId}`,
              authProvider: 'guest'
            }
          });
        }
        req.user = { id: guestUser.id, role: 'CUSTOMER', isGuest: true };
        return next();
      }

      return res.status(401).json({
        success: false,
        message: 'Authentication token is required (Bearer <token>)'
      });
    }

    const token = authHeader.split(' ')[1];
    const decoded = jwt.verify(token, JWT_SECRET);

    const userId = decoded.id || decoded.userId;
    if (!userId) {
      return res.status(401).json({
        success: false,
        message: 'Invalid token payload'
      });
    }

    // Attach user to request
    req.user = {
      id: userId,
      role: decoded.role || 'CUSTOMER'
    };

    next();
  } catch (error) {
    // If token verification failed, try guest fallback if guestId present
    const guestId = req.headers['x-guest-id'] || req.body?.guestId || req.query?.guestId;
    if (guestId) {
      try {
        let guestUser = await prisma.user.findFirst({
          where: { googleId: `guest_${guestId}` }
        });
        if (!guestUser) {
          guestUser = await prisma.user.create({
            data: {
              name: 'App Visitor',
              googleId: `guest_${guestId}`,
              authProvider: 'guest'
            }
          });
        }
        req.user = { id: guestUser.id, role: 'CUSTOMER', isGuest: true };
        return next();
      } catch (_) {}
    }

    return res.status(401).json({
      success: false,
      message: 'Invalid or expired authentication token',
      error: error.message
    });
  }
}

/**
 * Support Agent & Admin Authorization Middleware
 * Verifies that the authenticated user is registered as an active support agent or admin.
 */
async function requireAgent(req, res, next) {
  try {
    if (!req.user || !req.user.id) {
      return res.status(401).json({ success: false, message: 'Authentication required' });
    }

    // Admins have automatic access
    if (req.user.role === 'ADMIN') {
      return next();
    }

    // Check support_agents table
    const agent = await prisma.supportAgent.findUnique({
      where: { userId: req.user.id }
    });

    if (!agent || !agent.isActive) {
      return res.status(403).json({
        success: false,
        message: 'Support Agent privileges required'
      });
    }

    req.supportAgent = agent;
    next();
  } catch (error) {
    return res.status(500).json({
      success: false,
      message: 'Failed to verify agent authorization',
      error: error.message
    });
  }
}

/**
 * Super Admin Authorization Middleware
 */
function requireAdmin(req, res, next) {
  if (req.user?.role !== 'ADMIN') {
    return res.status(403).json({
      success: false,
      message: 'Super Admin access required'
    });
  }
  next();
}

module.exports = {
  authenticate,
  requireAgent,
  requireAdmin
};

